referenceFixTemplate:
public class Main {
    public static void main(String[] args) {
        int[] bowls = {3, 5, 7};
        try {
            System.out.println(bowls[3]);
        } catch (ArrayIndexOutOfBoundsException e) {
            System.out.println("越界了喵");
        } finally {
            System.out.println("碗收好了");
        }
        System.out.println("{tail}");
    }
}
